import java.util.Scanner;

public class Main {
    static final int SLOTS = 10;

    static int[] shelf = new int[SLOTS];
    static int[] used = new int[SLOTS];

    // 编号算门牌号：编号除以 10 的余数
    static int slotOf(int id) {
        return id % SLOTS;
    }

    // 存一只：从算出来的格子开始，有人住了就往后挪一格，还撞就再挪；住下时记一笔
    static void put(int id) {
        int slot = slotOf(id);
        while (used[slot] != 0) {
            slot = (slot + 1) % SLOTS;
        }
        shelf[slot] = id;
        used[slot] = 1;
    }

    // 找一只：从算出来的格子开始往后敲，答「敲了几次才找到」；敲到空格子就答 0
    static int find(int id) {
        int slot = slotOf(id);
        int tries = 0;
        while (used[slot] != 0) {
            tries++;
            if (shelf[slot] == id) {
                return tries;
            }
            slot = (slot + 1) % SLOTS;
        }
        return 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[64];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        for (int i = 0; i < n; i++) {
            put(a[i]);
        }

        int last = a[n - 1];
        int times = find(last);
        if (times > 0) {
            System.out.println("最后递进来的 " + last + "：比了 " + times + " 次");
        } else {
            System.out.println("最后递进来的 " + last + "：没找到");
        }

        if (find(0) > 0) {
            System.out.println("编号 0：找着了");
        } else {
            System.out.println("编号 0：没找到");
        }
    }
}
